const Certifications = () => {
    const certifications = [
        {
            title: 'AWS Generative AI Applications',
            issuer: 'Coursera & AWS',
            type: 'split',
            leftSvg: CourseraLogo,
            leftColor: '#2A73CC',
            rightIcon: 'fab fa-aws', // using FA icon since it rendered perfectly
            rightColor: '#FF9900',
            link: 'https://www.coursera.org/account/accomplishments/professional-cert/I1VH7C83GKB6'
        },
        {
            title: 'IBM Machine Learning Professional Certificate',
            issuer: 'IBM & Coursera',
            type: 'split',
            leftSvg: CourseraLogo,
            leftColor: '#2A73CC',
            rightSvg: IBMLogo,
            rightColor: '#0F62FE',
            link: 'https://www.coursera.org/account/accomplishments/professional-cert/BBA8HEIKGKYL'
        },
        {
            title: 'OCI AI Foundations Associate',
            issuer: 'Oracle University',
            type: 'single',
            svg: OracleLogo,
            color: '#F80000',
            link: 'https://catalog-education.oracle.com/ords/certview/sharebadge?id=7C04BE6C04D7D7D63217A5D0D9B9D159313248BA204AAC8B937FE438916E2E97'
        },
        {
            title: 'Intermediate Machine Learning',
            issuer: 'Kaggle',
            type: 'single',
            icon: 'fab fa-kaggle',
            color: '#20BEFF',
            link: 'https://www.kaggle.com/learn/certification/yassirchergui/intermediate-machine-learning'
        }
    ]

    return (
        <section className="section certifications" id="certifications">
            <div className="container">
                <div className="section-header">
                    <span className="section-tag">Credentials</span>
                    <h2 className="section-title">Certifications</h2>
                </div>
                <div className="certifications-grid">
                    {certifications.map((cert, index) => (
                        <a
                            href={cert.link}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="cert-card animate-fade-in-up"
                            key={index}
                            style={{ animationDelay: `${index * 0.1}s` }}
                        >
                            {cert.type === 'split' ? (
                                <div className="logo-split">
                                    <div className="logo-split-half logo-split-left" style={{ color: cert.leftColor }}>
                                        {cert.leftSvg}
                                    </div>
                                    <div className="logo-split-half logo-split-right" style={{ color: cert.rightColor }}>
                                        {cert.rightSvg ? cert.rightSvg : <i className={cert.rightIcon}></i>}
                                    </div>
                                </div>
                            ) : (
                                <div className="cert-icon-single" style={{ color: cert.color }}>
                                    {cert.svg ? cert.svg : <i className={cert.icon}></i>}
                                </div>
                            )}
                            <div className="cert-content">
                                <h3 className="cert-title">{cert.title}</h3>
                                <p className="cert-issuer">{cert.issuer}</p>
                            </div>
                            <div className="cert-badge">
                                <i className="fas fa-check-circle"></i>
                            </div>
                        </a>
                    ))}
                </div>
            </div>
        </section>
    )
}

export default Certifications
